namespace TUGraz.Vecto.UnitTests.TestCases.Components.HybridStrategy;



public class HybridStrategyCostCalculationTest
{

	public class HybridStrategyCalculateCost : AbstractHybridStrategy
	{
		public HybridStrategyCalculateCost(VectoRunData runData, IVehicleContainer vehicleContainer, IPowertrainContainer powertrainContainer) : base(runData, vehicleContainer, powertrainContainer) { }

		#region Overrides of AbstractHybridStrategy

		protected override IResponse RequestDryRun(Second absTime, Second dt, NewtonMeter outTorque, PerSecond outAngularVelocity,
			GearshiftPosition nextGear, HybridStrategyResponse cfg)
		{
			throw new NotImplementedException();
		}

		protected override void CheckGearshiftLimits(HybridResultEntry tmp, IResponse resp)
		{
			// Fake check of gearshift line checks here - use expected values
			// avoids adaptation of testdata in case the gearshift lines change
			if (TestContext.CurrentContext.Test.Arguments.Length > 0) {
				var testparams =
					CostCalculationDataExtension.ParseString(TestContext.CurrentContext.Test.Arguments.FirstOrDefault()?.ToString() ?? "");
				if (testparams.Expected.IngoreReason.EngineSpeedAboveUpshift()) {
					tmp.IgnoreReason |= HybridConfigurationIgnoreReason.EngineSpeedAboveUpshift;
				}

				if (testparams.Expected.IngoreReason.EngineSpeedBelowDownshift()) {
					tmp.IgnoreReason |= HybridConfigurationIgnoreReason.EngineSpeedBelowDownshift;
				}
			}
		}

		#endregion

		public void CostCalculation(IResponse resp, Second dt, HybridResultEntry tmp, bool allowIceOff, bool dryRun)
		{
			CalculateCosts(resp, dt, tmp, allowIceOff, dryRun);
		}
	}

