	[TestCaseSource(nameof(IterateTestDataNoDryRun))]
	public void TestCostCalculation_AMT_NoDryRun(string testDataStr)
	{
		TestCostCalculation(testDataStr, GearboxType.AMT, false);
	}

	[TestCaseSource(nameof(IterateTestDataDryRun))]
	public void TestCostCalculation_AMT_DryRun(string testDataStr)
	{
		TestCostCalculation(testDataStr, GearboxType.AMT, false);
	}

    [TestCaseSource(nameof(IterateTestDataAPTS))]
	public void TestCostCalculation_APTS_NoDryRun(string testDataStr)
	{
		TestCostCalculation(testDataStr, GearboxType.ATSerial, false);
	}

    [TestCaseSource(nameof(IterateTestDataAPTSTC))]
	public void TestCostCalculation_APTS_TC_NoDryRun(string testDataStr)
	{
		TestCostCalculation(testDataStr, GearboxType.ATSerial, true);
	}

    protected void TestCostCalculation(string testDataStr, GearboxType gbxType, bool respnseFromTC)
	{
		var testData = CostCalculationDataExtension.ParseString(testDataStr);

		var container = CreateContainer(testData.PowertrainInfo);
		var powertrainContainer = new PowertrainContainer(container.Object);
		var runData = GetVectoRunData(testData.ModelParams, gbxType);

		var dut = new HybridStrategyCalculateCost(runData, container.Object, powertrainContainer);

		var response = CreateResponse(testData.Response, respnseFromTC);
		var dt = testData.dt;
		var entry = new HybridResultEntry();
		dut.CostCalculation(response.Object, dt, entry, testData.AllowICEOff, testData.DryRun);

		Assert.AreEqual(testData.Expected.Cost, entry.Cost, 1e-6, "Cost");
		Assert.AreEqual(testData.Expected.FuelCosts, entry.FuelCosts, 1e-6, "FuelCosts");
		Assert.AreEqual(testData.Expected.BatCosts, entry.BatCosts, 1e-6, "Battery Costs");
		Assert.AreEqual(testData.Expected.IngoreReason, entry.IgnoreReason, "Ignore reason");
	}

	private static Mock<IVehicleContainer> CreateContainer(PowertrainInfo powertrainInfo)
	{
		var container = new Mock<IVehicleContainer>(MockBehavior.Strict).WithPowertrainDict();
		// var simpleContainer = new Mock<ISimpleVehicleContainer>(MockBehavior.Strict);
		var simplePowertrainContainer = new Mock<ISimplePowertrainContainer>(MockBehavior.Strict);
		var testPowertrain = new Mock<ITestPowertrain>(MockBehavior.Strict);
		// TestPowertrain = PowertrainBuilder.CreateTestPowertrain(DataBus, true);
		// SimplePowertrainContainer = TestPowertrain.Container.SimplePowertrains[powertrainContainer.AxleNumber];
		
		
		var ptBuilder = new Mock<ISimplePowertrainBuilder>(MockBehavior.Strict);
		ptBuilder.Setup(p => p.CreateTestPowertrain(It.IsAny<IVehicleContainer>(), It.IsAny<bool>())).Returns(testPowertrain.Object);

		testPowertrain.Setup(tp => tp.Container.SimplePowertrains[It.IsAny<AxleNumber>()]).Returns(simplePowertrainContainer.Object);
		
		
		
		
		var driver = new Mock<IDriverInfo>();
		var engine = new Mock<IEngineInfo>();
		var engineCtl = new Mock<IEngineControl>();
		var battery = new Mock<IRESSInfo>();
		var gearbox = new Mock<IGearboxInfo>();
		
		container.Setup(x => x.SimplePowertrainBuilder).Returns(ptBuilder.Object);
		container.Setup(x => x.DriverInfo).Returns(driver.Object);
		container.Setup(x => x.EngineInfo).Returns(engine.Object);
		container.Setup(x => x.EngineCtl).Returns(engineCtl.Object);
		container.Setup(x => x.BatteryInfo).Returns(battery.Object);
		container.Setup(x => x.GearboxesInfo).Returns(new List<IGearboxInfo>() {
			gearbox.Object
		});

		driver.Setup(x => x.DrivingAction).Returns(powertrainInfo.DrivingAction);
		engine.Setup(x => x.EngineN95hSpeed).Returns(powertrainInfo.EngineN95hSpeed);
		engine.Setup(x => x.EngineSpeed).Returns(powertrainInfo.EngineSpeed);
		engineCtl.Setup(x => x.CombustionEngineOn).Returns(powertrainInfo.CombustionEngineOn);
		battery.Setup(x => x.StoredEnergy).Returns(powertrainInfo.BatteryStoredEnergy);
		battery.Setup(x => x.StateOfCharge).Returns(powertrainInfo.BatterySoC);
		gearbox.Setup(x => x.Gear).Returns(new GearshiftPosition(powertrainInfo.GearboxCurrentGear));

        return container;
	}

	private Mock<IResponse> CreateResponse(ResponseValues responseValues, bool respnseFromTc)
	{
		var response = new Mock<IResponse>();
		response.Setup(x => x.Gearbox).Returns(new GearboxResponse() {
			Gear = new GearshiftPosition(responseValues.ResponseGear)
		});
		response.Setup(x => x.Engine).Returns(new EngineResponse() {
			DynamicFullLoadTorque = responseValues.EngineDynamicFullLoadTorque,
			DynamicFullLoadPower = responseValues.EngineDynamicFulloadPower,
			TotalTorqueDemand = responseValues.EngineTotalTorqueDemand,
			DragPower = responseValues.EngineDragPower,
			EngineSpeed = responseValues.EngineSpeed,
			TorqueOutDemand = responseValues.EngineTorqueOutDemand
		});
		response.Setup(x => x.ElectricSystem).Returns(new ElectricSystemResponseSuccess(this) {
			RESSPowerDemand = responseValues.REESSPowerDemand,
			RESSResponse = new RESSResponseSuccess(this) {
				PowerDemand = responseValues.REESSResponsePowerDemand,
				MaxDischargePower = responseValues.REESSResponseMaxDischargePower,
				MaxChargePower = responseValues.REESSResponseMaxChargePower
			}
		});
		if (respnseFromTc) {
			response.Setup(x => x.Source).Returns(new Mock<ITorqueConverter>().Object);
		}
		return response;
	}

	private VectoRunData GetVectoRunData(ModelParams modelParams, GearboxType gbxType)
	{
		var runData = new VectoRunData();

		var fcMap = new Mock<IFuelConsumptionMap>();
		fcMap.Setup(x => x.GetFuelConsumptionValue(It.IsAny<NewtonMeter>(), It.IsAny<PerSecond>()))
			.Returns((NewtonMeter tq, PerSecond w) => tq.IsEqual(0) && w.IsEqual(modelParams.EngineIdleSpeed)
				? 0.01.SI<KilogramPerSecond>()
				: modelParams.FuelConsumption);

		runData.ElectricMachinesSinglePwt = new List<Tuple<PowertrainPosition, ElectricMotorData>>() {
			Tuple.Create(PowertrainPosition.HybridP2, new ElectricMotorData())
		};
		runData.EngineData = new CombustionEngineData() {
			IdleSpeed = modelParams.EngineIdleSpeed,
			Inertia = modelParams.Inertia,
			Fuels = new List<CombustionEngineFuelData>() {
				new CombustionEngineFuelData() {
					FuelData = FuelData.Diesel,
					ConsumptionMap = fcMap.Object
				}
			},
			FullLoadCurves = new Dictionary<uint, EngineFullLoadCurve>() {
				{0, new EngineFullLoadCurve(new List<EngineFullLoadCurve.FullLoadCurveEntry>() {
					new() {
						EngineSpeed = 600.RPMtoRad(),
						TorqueDrag = -20.SI<NewtonMeter>(),
						TorqueFullLoad = 800.SI<NewtonMeter>()
					},
					new() {
						EngineSpeed = 2000.RPMtoRad(),
						TorqueDrag = -20.SI<NewtonMeter>(),
						TorqueFullLoad = 800.SI<NewtonMeter>()
					}
				}, DeclarationData.PT1)}

			},
			EngineStartTime = modelParams.EngineStartTime
		};
		runData.GearshiftParametersSinglePwt = new ShiftStrategyParameters() {
			AllowedGearRangeFC = modelParams.GearshiftParamsAllowedGearRange
		};

		runData.GearboxSinglePwt = new GearboxData() {
			Type = gbxType,
			Gears = new Dictionary<uint, GearData>()
		};
		for (var i = 1u; i <= modelParams.GearboxNumGears; i++) {
			runData.GearboxSinglePwt.Gears[i] = new GearData();
		}
		runData.HybridStrategyParameters = new HybridStrategyParameters() {
			MinICEOnTime = modelParams.HybridStrategyMinIceOnTime
		};

		return runData;
	}
